 *
 * @param  array<string, mixed>  $context
 */
private function logSubstituteDiag(string $step, array $context = []): void
{
    try {
        Log::info('[substitute]', array_merge([
            'step' => $step,
            't' => now()->format('Y-m-d H:i:s.v'),
        ], $context));
    } catch (\Throwable $e) {
        // 不因 log 失敗影響代課
    }
}

